-- SOMENTE LEITURA: SELECT unico, uma linha, receipt JSON; sem linhas de clientes/Auth/Vault.
select jsonb_build_object('snapshot',s,'normalized',(select src.doc-'relations'-'functions'-'u3_function_details'||jsonb_build_object('relations',(select jsonb_agg(rel-'columns'-'constraints'-'indexes'||jsonb_build_object('columns',(select jsonb_agg(item order by pos) from jsonb_array_elements(rel->'columns') with ordinality vals(item,pos) where not exists(select 1 from jsonb_array_elements('[["creatives","pessoa_id","uuid"]]'::jsonb) pair where pair->>0=rel->>'relname' and pair->>1=item->>'name')),'constraints',(select jsonb_agg(item order by item->>'name') from jsonb_array_elements(rel->'constraints') with ordinality vals(item,pos) where not exists(select 1 from jsonb_array_elements('[["creatives","creatives_uso_check"],["creatives","creatives_pessoa_negocio_fkey"]]'::jsonb) pair where pair->>0=rel->>'relname' and pair->>1=item->>'name')),'indexes',(select jsonb_agg(item order by item->>'name') from jsonb_array_elements(rel->'indexes') with ordinality vals(item,pos) where not exists(select 1 from jsonb_array_elements('[["creatives","creatives_pessoa_id_idx"]]'::jsonb) pair where pair->>0=rel->>'relname' and pair->>1=item->>'name'))) order by rel->>'nspname',rel->>'relname') from jsonb_array_elements(src.doc->'relations') rel where not (rel->>'relname'=any(array['pessoas_do_negocio','entrevistas','propostas_de_perfil','itens_da_proposta','divergencias_de_cadastro']))),'functions',(select jsonb_agg(f order by f->>'schema',f->>'name',f->>'identity') from jsonb_array_elements(src.doc->'functions') f where f->>'name' not in ('aplicar_proposta','escrever_apenas_se_livre')),'u3_function_details','[]'::jsonb) from(select s doc) src),'delta',(select jsonb_build_object('columns',(select coalesce(jsonb_agg(jsonb_build_object('table',rel->>'relname','object',item) order by rel->>'relname',item->>'name'),'[]'::jsonb) from jsonb_array_elements(src.doc->'relations') rel cross join lateral jsonb_array_elements(rel->'columns') item where exists(select 1 from jsonb_array_elements('[["creatives","pessoa_id","uuid"]]'::jsonb) pair where pair->>0=rel->>'relname' and pair->>1=item->>'name')),'constraints',(select coalesce(jsonb_agg(jsonb_build_object('table',rel->>'relname','object',item) order by rel->>'relname',item->>'name'),'[]'::jsonb) from jsonb_array_elements(src.doc->'relations') rel cross join lateral jsonb_array_elements(rel->'constraints') item where exists(select 1 from jsonb_array_elements('[["creatives","creatives_uso_check"],["creatives","creatives_pessoa_negocio_fkey"]]'::jsonb) pair where pair->>0=rel->>'relname' and pair->>1=item->>'name')),'indexes',(select coalesce(jsonb_agg(jsonb_build_object('table',rel->>'relname','object',item) order by rel->>'relname',item->>'name'),'[]'::jsonb) from jsonb_array_elements(src.doc->'relations') rel cross join lateral jsonb_array_elements(rel->'indexes') item where exists(select 1 from jsonb_array_elements('[["creatives","creatives_pessoa_id_idx"]]'::jsonb) pair where pair->>0=rel->>'relname' and pair->>1=item->>'name')),'tables',(select coalesce(jsonb_agg(rel order by rel->>'nspname',rel->>'relname'),'[]'::jsonb) from jsonb_array_elements(src.doc->'relations') rel where rel->>'relname'=any(array['pessoas_do_negocio','entrevistas','propostas_de_perfil','itens_da_proposta','divergencias_de_cadastro'])), 'functions',(select coalesce(jsonb_agg(f order by f->>'schema',f->>'name',f->>'identity'),'[]'::jsonb) from jsonb_array_elements(src.doc->'functions') f where f->>'name' in('aplicar_proposta','escrever_apenas_se_livre')),'details',src.doc->'u3_function_details') from(select s doc) src)) as receipt from(select (select jsonb_build_object(
'relations',(select jsonb_agg(obj order by obj->>'nspname',obj->>'relname') from (select jsonb_build_object('nspname',n.nspname,'relname',c.relname,'relkind',c.relkind,'owner',c.relowner::regrole::text,'rls',c.relrowsecurity,'forced',c.relforcerowsecurity,
'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid)) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),
'constraints',(select jsonb_agg(jsonb_build_object('name',k.conname,'def',pg_get_constraintdef(k.oid)) order by k.conname) from pg_constraint k where k.conrelid=c.oid and k.contype<>'n'),
'indexes',(select jsonb_agg(jsonb_build_object('name',ic.relname,'def',pg_get_indexdef(i.indexrelid)) order by ic.relname) from pg_index i join pg_class ic on ic.oid=i.indexrelid where i.indrelid=c.oid),
'triggers',(select jsonb_agg(jsonb_build_object('name',tg.tgname,'def',pg_get_triggerdef(tg.oid),'function',tg.tgfoid::regprocedure::text,'handler_md5',md5(pg_get_functiondef(tg.tgfoid))) order by tg.tgname) from pg_trigger tg where tg.tgrelid=c.oid and not tg.tgisinternal),
'policies',(select jsonb_agg(jsonb_build_object('name',p.polname,'cmd',p.polcmd,'roles',(select jsonb_agg(case when x=0 then 'PUBLIC' else x::regrole::text end order by case when x=0 then 'PUBLIC' else x::regrole::text end) from unnest(p.polroles) x),'permissive',p.polpermissive,'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid)) order by p.polname) from pg_policy p where p.polrelid=c.oid),
'table_acl',(select jsonb_agg(jsonb_build_object('role',case when a.grantee=0 then 'PUBLIC' else a.grantee::regrole::text end,'grantor',a.grantor::regrole::text,'privilege',a.privilege_type,'grantable',a.is_grantable) order by case when a.grantee=0 then 'PUBLIC' else a.grantee::regrole::text end,a.privilege_type,a.grantor::regrole::text) from aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a),
'column_acl',(select jsonb_agg(jsonb_build_object('column',at.attname,'role',case when a.grantee=0 then 'PUBLIC' else a.grantee::regrole::text end,'privilege',a.privilege_type,'grantable',a.is_grantable) order by at.attname,case when a.grantee=0 then 'PUBLIC' else a.grantee::regrole::text end,a.privilege_type) from pg_attribute at cross join lateral aclexplode(at.attacl) a where at.attrelid=c.oid and at.attnum>0 and not at.attisdropped)
) as obj from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind='r' and ((n.nspname='public' and c.relname in ('businesses','campaigns','creatives','ad_accounts','meta_connections','metrics_daily','exclusoes_de_dados','commercial_order_units','clientes','execucoes','criativos','campanhas_meta','metricas_diarias','respostas_do_dono','execucoes_de_rotina','perguntas_apresentadas','campanhas_criacao','identidade_visual','narrativa_negocio','pessoas_do_negocio','entrevistas','propostas_de_perfil','itens_da_proposta','divergencias_de_cadastro')) or(n.nspname='vault' and c.relname='secrets'))) rels),
'functions',(select jsonb_agg(obj order by obj->>'schema',obj->>'name',obj->>'identity') from (select jsonb_build_object('schema',n.nspname,'name',p.proname,'identity',pg_get_function_identity_arguments(p.oid),'return_type',p.prorettype::regtype::text,'language',l.lanname,'definer',p.prosecdef,'volatility',p.provolatile,'strict',p.proisstrict,'parallel',p.proparallel,'leakproof',p.proleakproof,'retset',p.proretset,'kind',p.prokind,'config',p.proconfig,'body_md5',md5(p.prosrc),'owner',p.proowner::regrole::text,'acl',(select jsonb_agg(jsonb_build_object('role',case when a.grantee=0 then 'PUBLIC' else a.grantee::regrole::text end,'privilege',a.privilege_type,'grantable',a.is_grantable) order by case when a.grantee=0 then 'PUBLIC' else a.grantee::regrole::text end,a.privilege_type) from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a)) as obj from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang where n.nspname in ('public','private') and p.proname in ('marcar_conexao_meta_quebrada','desautorizar_meta','apagar_dados_da_meta','status_da_exclusao','owns_business','registrar_procedencia','procedencia_do_campo','set_atualizado_em','aplicar_proposta','escrever_apenas_se_livre')) funcs),
'u3_function_details',(select coalesce(jsonb_agg(jsonb_build_object('name',p.proname,'arguments',pg_get_function_arguments(p.oid),'variadic',p.provariadic::text,'support',p.prosupport::text) order by p.proname),'[]'::jsonb) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('aplicar_proposta','escrever_apenas_se_livre')),
'defaults',(select jsonb_agg(to_jsonb(d) order by d.oid) from pg_default_acl d),
'ledger',(select jsonb_agg(jsonb_build_object('version',version,'name',name) order by version,name) from supabase_migrations.schema_migrations),
'incoming_fks',(select jsonb_agg(jsonb_build_object('source',k.conrelid::regclass::text,'target',k.confrelid::regclass::text,'name',k.conname,'def',pg_get_constraintdef(k.oid)) order by k.conrelid::regclass::text,k.conname) from pg_constraint k where k.contype='f' and k.confrelid in ('public.meta_connections'::regclass,'public.ad_accounts'::regclass,'public.metrics_daily'::regclass)),
'vault_access',jsonb_build_object('usage',has_schema_privilege('postgres','vault','USAGE'),'select',has_table_privilege('postgres','vault.secrets','SELECT'),'delete',has_table_privilege('postgres','vault.secrets','DELETE'))
)) s) capture;
